import json
H,W=18,15
g=[[0]*W for _ in range(H)]
colors=[2,3,1,8,7]
patterns=[[0,0,1,1,0,0],[0,1,0,0,1,0],[1,1,1,1,1,1]]
for i,c in enumerate(colors):
    for dr,pat in enumerate(patterns):
        for dc,v in enumerate(pat):
            if v:g[3*i+dr][3+dc]=c
print(len(g),[len(r) for r in g]); print(json.dumps(g,separators=(',',':')))

import json
msgs=[json.loads(x) for x in p.read_text().splitlines()]
